      "kind": "theorem",
      "type": "∀ {M : Type u_1} {ι : Type u_2} [inst : SeminormedCommGroup M] [IsUltrametricDist M] (s : Finset ι) (f : ι → M),\n  ‖∏ i ∈ s, f i‖₊ ≤ s.sup fun x => ‖f x‖₊"
    },
    {
      "name": "IsUltrametricDist.norm_prod_le_of_forall_le_of_nonneg",
      "module_name": "Mathlib.Analysis.Normed.Group.Ultra",
      "kind": "theorem",
      "type": "∀ {M : Type u_1} {ι : Type u_2} [inst : SeminormedCommGroup M] [IsUltrametricDist M] {s : Finset ι} {f : ι → M} {C : ℝ},\n  0 ≤ C → (∀ i ∈ s, ‖f i‖ ≤ C) → ‖∏ i ∈ s, f i‖ ≤ C"
